    private static void FieldEquipmentChildren()
    {
        foreach(var scene in new[]{"field-lion","field-ox"})
        {
            var(g,r)=Start(scene);var gear=V(g,0).Hand.First().Id;Place(g,gear);int? grain=null;if(scene=="field-lion"){Use(g,"lose");Play(g);}else{grain=V(g,0).Hand.First().Id;Use(g,"grain",cards:[grain.Value]);Play(g);}Use(g,"empty");Activate(g,Qiejian);Reach(g,()=>Branch(g,"discard"));var paid=g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.QuHuang?.Op==SkillProgramEffectOp.ResolveQiejianLastHandLoss).Id;Choose(g,"discard",gear);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==(scene=="field-lion"?Health:Watch));Need(E<QuHuangEntityMovedEvent>(g).Count(e=>e.FrameId==paid&&e.CardId==gear&&e.To==CardLocation.DiscardPile)==1,"Qiejian's chosen field equipment is genuinely discarded before its native removal child pauses.");g=Cold(g,r);Continue(g);Reach(g,()=>E<QuHuangCompletedEvent>(g).Any(e=>e.FrameId==paid));if(scene=="field-lion")Need(V(g,0).Hp==V(g,0).MaxHp,"The field discard inherits actual Silver Lion recovery and its native HP child.");else Need(Zone(g,grain!.Value)==CardLocation.DiscardPile&&g.CardMovements.Any(m=>m.CardId==grain&&m.From==CardLocation.WoodenOxGrain(0)&&m.Reason==CardMoveReasons.WoodenOxGrainDiscard)&&V(g,0).Hp==V(g,0).MaxHp-1,"Real Wooden Ox grain disposal and the movement child's damage return through the same paid Qiejian receipt.");Need(g.CardMovements.Count(m=>m.CardId==gear&&m.Reason.Value=="skill-program.qu-huang.qiejian.discard")==1,"Cold native equipment-removal children cannot charge the field discard twice.");_=Cold(g,r);
        }
    }
    private static void AssertHeldPrivacy(GameEngine g,int[] own,int[] other,int second)
    {
        Need((g.CreateSnapshot(0).PrivateRevealedCards??[]).Select(c=>c.Id).Order().SequenceEqual(own.Order())&&(g.CreateSnapshot(1).PrivateRevealedCards??[]).Select(c=>c.Id).Order().SequenceEqual(other.Order())&&Enumerable.Range(2,2).All(s=>g.CreateSnapshot(s).PrivateRevealedCards is null)&&Enumerable.Range(0,4).All(s=>g.CreateSnapshot(s).ProcessingCardCount==0&&!g.CreateSnapshot(s).PublicRevealedCards.Any(c=>own.Concat(other).Contains(c.Id))),"Held original faces stay private to their real former holder and disappear from public Processing counts/faces at hold stage "+second+".");
    }
    private static void IssuePlayDebt(GameEngine g){var id=V(g,0).Hand.First().Id;Place(g,id);Use(g,"equipment-empty");Reach(g,()=>Branch(g,"defer"));Choose(g,"defer");Play(g);}
    private static void Place(GameEngine g,int id){Use(g,"place",[0],[id]);Play(g);}
    private static PlayerSnapshot V(GameEngine g,int seat)=>g.CreateSnapshot(seat).Players[seat];
    private static CardLocation Zone(GameEngine g,int id)=>g.CreateCardZoneDiagnostics().Single(z=>z.CardId==id).Location;
    private static bool Has(GameEngine g,int seat,string skill)=>V(g,seat).Skills!.Any(s=>s.Id==skill);
    private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
    private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
    private static bool Branch(GameEngine g,string branch)=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="qu-huang"&&c.Parameters.GetValueOrDefault("branch")==branch)==true;
    private static bool Offer(GameEngine g,string skill)=>P(g)is{PlayerSeat:0}p&&p.SkillPrompt?.SkillId==skill&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    private static void Need(bool value,string text){if(!value)throw new InvalidOperationException(Scene+": "+text);}
    private static void Accept(GameEngine g,GameCommand command){try{var result=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([command])).Single());Need(result.Accepted,result.Error?.Message??"Rejected real Qu Huang command.");}catch(Exception ex){throw new InvalidOperationException(command.GetType().Name+" cause="+ex.GetType().Name+": "+ex.Message+" "+Diagnostic(g),ex);}}
    private static void Answer(GameEngine g,Func<PromptChoice,bool> test){var p=P(g)!;var c=p.Choices.FirstOrDefault(test);Need(p.PlayerSeat==0&&c is not null,"Missing private human choice "+Diagnostic(g));Accept(g,new AnswerPromptCommand(0,p.PromptId,c!.Id,g.Revision));}
    private static void Choose(GameEngine g,string branch,int? card=null,int? seat=null)=>Answer(g,c=>c.Parameters.GetValueOrDefault("branch")==branch&&(card is null||c.Cards.SequenceEqual([card.Value]))&&(seat is null||c.Targets.SequenceEqual([seat.Value])));
    private static void Activate(GameEngine g,string skill){Reach(g,()=>Offer(g,skill));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");}
    private static void Continue(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("option-id")=="continue");
    private static void Use(GameEngine g,string id,int[]? seats=null,int[]? cards=null)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,cards??[],seats??(id=="equipment-empty"?[0]:[]),g.Revision,P(g)!.PromptId));
    private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static void FinishOwn(GameEngine g)=>Reach(g,()=>!g.ResolutionStack.OfType<ProgramSkillFrame>().Any(f=>f.QuHuang is not null));
    private static void Reach(GameEngine g,Func<bool> done,[CallerMemberName]string method="",[CallerLineNumber]int line=0)
    {
        for(var i=0;i<360;i++)
        {
            if(done())return;Need(g.State.Winner==Winner.None,$"Unexpected completion {method}:{line} "+Diagnostic(g));var p=P(g);
            if(p is null||p.PlayerSeat!=0)Accept(g,new AdvanceOneStepCommand(g.Revision));
            else if(p.Kind==DecisionKind.PlayCard)End(g);
            else if(p.SkillPrompt?.SkillId is Watch or Health)Continue(g);
            else if(p.SkillPrompt?.SkillId==Setup&&p.Choices.Any(c=>c.Targets.SequenceEqual([0])))Answer(g,c=>c.Targets.SequenceEqual([0]));
            else if(Branch(g,"block"))Choose(g,"block");
            else if(Branch(g,"defer"))Choose(g,"defer");
            else if(Branch(g,"swap"))Answer(g,c=>c.Parameters.GetValueOrDefault("branch")=="swap");
            else if(p.Kind is DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification)Answer(g,c=>c.Cards.Count==0);
            else if(p.Kind==DecisionKind.RescueDying)Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"let-die"or"pass");
            else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");
            else throw new InvalidOperationException($"Unexpected prompt {method}:{line} "+Diagnostic(g));
        }
        throw new InvalidOperationException($"Missing boundary {method}:{line} "+Diagnostic(g));
    }
    private static string Diagnostic(GameEngine g)=>JsonSerializer.Serialize(new{Scene,g.State.TurnNumber,g.State.CurrentSeat,g.State.Winner,Players=Enumerable.Range(0,4).Select(s=>new{s,V(g,s).Hp,V(g,s).HandCount,V(g,s).IsAlive}),Prompt=P(g)is{}p?new{p.Kind,p.PlayerSeat,Skill=p.SkillPrompt?.SkillId,Choices=p.Choices.Take(4).Select(c=>new{c.Cards,c.Targets,c.Parameters})}:null,Frames=g.ResolutionStack.TakeLast(5).Select(f=>new{f.Id,Type=f.GetType().Name,Stage=(f as ProgramSkillFrame)?.QuHuang?.Stage}),Facts=g.Events.TakeLast(3).Select(e=>e.Payload.ToString())});
